escenas.animacion:
const ac = A.accent;
A.bg('#06121f', '#0b2236');
const tE = A.k('Estatua', 0.333), tL = A.k('Libertad', 1.333), tN = A.k('Nueva', 2.333);
const tD = A.k('desarmada…', 3.0), t214 = A.k('214', 3.667), tC = A.k('cajas.', 4.0);
const AMBER = '#FFB74D';

// --- Skyline de Nueva York ---
const rs = A.rand(7);
for (let i = 0; i < 15; i++) {
  const x = 90 + i * 62, w = 48, h = 90 + rs() * 230;
  const p = A.p(tN + i * 0.03, 0.55, 'glide');
  if (p <= 0) continue;
  const hh = h * p;
  ctx.save();
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = '#0f2a44';
  ctx.strokeStyle = '#7fa8c9';
  ctx.lineWidth = 2;
  ctx.fillRect(x, 1100 - hh, w, hh);
  ctx.strokeRect(x, 1100 - hh, w, hh);
  ctx.fillStyle = '#9fd3e8';
  for (let wy = 1100 - hh + 14; wy < 1090; wy += 26) {
    for (let wx = x + 8; wx < x + w - 8; wx += 14) ctx.fillRect(wx, wy, 5, 8);
  }
  ctx.restore();
}
// agua
const pw = A.p(tN, 0.6, 'softLand');
if (pw > 0) {
  const wv = [];
  for (let x = 60; x <= 1020; x += 20) wv.push([x, 1104 + Math.sin(x * 0.03 + t * 4) * 4]);
  A.line(wv, { stroke: ac, lw: 3, alpha: 0.6 * pw, progress: pw });
}

// --- Silueta de la estatua ---
const body = [[455,1100],[625,1100],[610,950],[615,820],[608,720],[630,600],[640,520],[664,522],[652,610],[640,720],[598,705],[588,684],[532,684],[505,700],[482,760],[470,820],[498,842],[478,900],[468,1000]];
const P = new Path2D();
P.moveTo(body[0][0], body[0][1]);
for (const q of body) P.lineTo(q[0], q[1]);
P.closePath();
P.moveTo(590, 648); P.arc(560, 648, 30, 0, Math.PI * 2);
for (let s = 0; s < 5; s++) {
  const a = -Math.PI * (0.85 - s * 0.175);
  const bx = 560 + Math.cos(a) * 26, by = 648 + Math.sin(a) * 26;
  const px = -Math.sin(a) * 9, py = Math.cos(a) * 9;
  P.moveTo(bx + px, by + py); P.lineTo(560 + Math.cos(a) * 62, 648 + Math.sin(a) * 62); P.lineTo(bx - px, by - py); P.closePath();
}
P.moveTo(674, 495); P.ellipse(652, 495, 20, 30, 0, 0, Math.PI * 2);

const shake = t > tD ? 16 * (1 - A.p(tD, 0.45, 'cruise')) : 0;

if (t < tD) {
  const po = A.p(tE, 1.1, 'softInOut');
  const pf = A.p(tE + 0.5, 0.8, 'softLand');
  const pre = A.clamp((t - (tD - 0.35)) / 0.35);
  A.with(() => {
    if (pf > 0) {
      ctx.save();
      ctx.globalAlpha = 0.85 * pf;
      ctx.fillStyle = '#1d6f7a';
      ctx.fill(P);
      ctx.restore();
      try { A.lib.hatch(ctx, body, { angle: 0.8, spacing: 14, width: 2, color: 'rgba(6,18,31,0.45)' }); } catch (e) {}
    }
    A.line(body.concat([body[0]]), { stroke: ac, lw: 5, progress: po });
    if (po > 0.3) A.circle(560, 648, 30, { stroke: ac, lw: 5, alpha: A.clamp((po - 0.3) * 3) });
    // antorcha
    const pt = A.p(tL, 0.5, 'popOver');
    if (pt > 0) {
      const fl = 1 + Math.sin(t * 18) * 0.06;
      try { A.lib.glowDot(ctx, 652, 495, 60 * pt * fl, { color: AMBER }); } catch (e) {}
      A.circle(652, 497, 18 * pt * fl, { fill: AMBER, glow: 30 });
      A.circle(652, 500, 8 * pt, { fill: '#fff' });
    }
    // grietas: el momento de espera antes de la ruptura
    if (pre > 0) {
      const rc = A.rand(99);
      for (let c = 0; c < 6; c++) {
        let x = 470 + rc() * 150, y = 620 + rc() * 440;
        const pts = [[x, y]];
        for (let s = 0; s < 4; s++) { x += (rc() - 0.5) * 70; y += (rc() - 0.3) * 60; pts.push([x, y]); }
        A.line(pts, { stroke: '#ffffff', lw: 3, progress: pre, alpha: 0.9 });
      }
    }
  }, { x: 540, y: 1100, scale: 1 + Math.sin(t * 2) * 0.005 + (pre > 0 ? Math.sin(t * 60) * 0.004 * pre : 0) });
}

// --- Bloques y cajas ---
const cells = [];
for (let y = 1090; y > 440; y -= 20) for (let x = 450; x < 680; x += 20) if (ctx.isPointInPath(P, x, y)) cells.push([x, y]);

const crateAt = (i) => [260 + (i % 15) * 40, 1080 - Math.floor(i / 15) * 40];
const tcOf = (i) => t214 - 0.25 + (i / 214) * 0.6;

if (t >= tD) {
  A.with(() => {
    // cajas
    for (let i = 0; i < 214; i++) {
      const tc = tcOf(i);
      if (t < tc) continue;
      const [X, Y] = crateAt(i);
      const s = A.pop(tc, 0.3) * 34;
      ctx.save();
      ctx.translate(X, Y);
      ctx.fillStyle = '#3a2410';
      ctx.strokeStyle = AMBER;
      ctx.lineWidth = 2.5;
      ctx.fillRect(-s / 2, -s / 2, s, s);
      ctx.strokeRect(-s / 2, -s / 2, s, s);
      ctx.beginPath();
      ctx.moveTo(-s / 2, -s / 2); ctx.lineTo(s / 2, s / 2);
      ctx.moveTo(s / 2, -s / 2); ctx.lineTo(-s / 2, s / 2);
      ctx.globalAlpha = 0.6; ctx.stroke();
      ctx.restore();
    }
    // bloques en vuelo
    const e = A.p(tD, 0.28, 'crashIn');
    for (let j = 0; j < cells.length; j++) {
      const [cx, cy] = cells[j];
      const r = A.rand(j + 11);
      const ox = (cx - 560) * 0.25 + (r() - 0.5) * 50, oy = (cy - 800) * 0.08 + (r() - 0.5) * 50 - 15;
      const rot0 = (r() - 0.5) * 2.4;
      let x, y, sz, rot, al = 1;
      if (j < 214) {
        const tc = tcOf(j);
        if (t >= tc) continue;
        const fs = Math.max(tD + 0.22, tc - 0.4);
        const f = A.p(fs, tc - fs, 'whip');
        const [X, Y] = crateAt(j);
        x = A.lerp(cx + ox * e, X, f); y = A.lerp(cy + oy * e, Y, f);
        sz = A.lerp(19, 30, f); rot = rot0 * e * (1 - f);
      } else {
        x = cx + ox * e * 2; y = cy + oy * e * 2; sz = 19; rot = rot0 * e;
        al = 1 - A.p(tD + 0.2, 0.4, 'softInOut');
        if (al <= 0) continue;
      }
      ctx.save();
      ctx.globalAlpha = al;
      ctx.translate(x, y); ctx.rotate(rot);
      ctx.fillStyle = '#1d6f7a'; ctx.strokeStyle = ac; ctx.lineWidth = 2;
      ctx.fillRect(-sz / 2, -sz / 2, sz, sz); ctx.strokeRect(-sz / 2, -sz / 2, sz, sz);
      ctx.restore();
    }
  }, { shake });
  A.flash(tD, 0.25, 0.35);
}

// --- Textos en la zona secundaria ---
const pdA = A.p(tD, 0.35, 'crashIn'), pdOut = A.p(t214 - 0.1, 0.25, 'accelExit');
if (pdA > 0 && pdOut < 1) {
  A.text('DESARMADA', 540, 1520, { size: 100, color: '#ffffff', weight: 900, align: 'center', alpha: pdA * (1 - pdOut), stroke: '#06121f', strokeWidth: 8 });
}
if (t >= t214) {
  const pc = A.p(t214, 0.45, 'softLand');
  A.with(() => {
    A.text(A.counter(0, 214, pc, 0), 540, 1560, { size: 250, color: ac, weight: 900, align: 'center', stroke: '#06121f', strokeWidth: 10 });
  }, { x: 540, y: 1480, scale: A.pop(t214, 0.4) });
}
if (t >= tC) {
  A.rings(540, 1480, tC, { count: 3, speed: 500, gap: 0.12, maxR: 420, color: AMBER, lw: 4, alpha: 0.6 });
  A.with(() => {
    A.text('CAJAS', 540, 1700, { size: 90, color: AMBER, weight: 900, align: 'center' });
  }, { x: 540, y: 1670, scale: A.pop(tC, 0.4) });
}

const ctx2 = ctx;
const AC = A.accent || '#FFD400';
const kF = A.k('Francia.', 1.333), kD = A.k('diseñó', 2.0), kB = A.k('Bartholdi,', 3.0);
const kE = A.k('esqueleto', 4.0), kH = A.k('hierro', 4.667), kG = A.k('Gustave', 5.667);
const kEi = A.k('Eiffel:', 6.0), kM = A.k('mismo', 6.667), kT = A.k('torre.', 7.667);

A.bg('#0b1630', '#050a18', true);

// ---------- partículas sutiles de fondo ----------
A.particles(18, 7, (i, rnd) => {
  const x = rnd() * 1080, y0 = 420 + rnd() * 700;
  const y = y0 - ((t * (10 + rnd() * 20)) % 120);
  A.circle(x, y, 2 + rnd() * 2, { fill: AC, alpha: 0.12 + 0.1 * Math.sin(t * 2 + i) });
});

// ---------- CAJA DE REGALO ----------
const boxAlpha = 1 - A.p(kD + 0.35, 0.6, 'softInOut');
if (boxAlpha > 0.01) {
  const sc = A.pop(0.05, 0.5);
  const wig = t < kD ? Math.sin(t * 14) * 3 * A.p(0.6, 0.3) : 0;
  const lidP = A.p(kD - 0.1, 0.55, 'whip');
  ctx.save();
  ctx.globalAlpha = boxAlpha;
  ctx.translate(540, 1100);
  ctx.scale(sc, sc);
  ctx.rotate(wig * 0.01);
  ctx.translate(-540, -1100);
  // cuerpo
  A.rect(390, 880, 300, 220, { r: 10, fill: '#13254a', stroke: '#ffffff', lw: 5 });
  A.lib.hatch(ctx, [[395, 885], [685, 885], [685, 1095], [395, 1095]], { angle: 0.8, spacing: 16, width: 1.5, color: 'rgba(255,255,255,0.12)' });
  A.rect(525, 880, 30, 220, { fill: AC });
  // tapa
  ctx.save();
  ctx.translate(540, 870 - 320 * lidP);
  ctx.rotate(-0.6 * lidP);
  A.rect(-170, -40, 340, 60, { r: 10, fill: '#1a3160', stroke: '#ffffff', lw: 5 });
  A.rect(-15, -40, 30, 60, { fill: AC });
  // lazo
  A.circle(-32, -58, 26, { stroke: AC, lw: 10 });
  A.circle(32, -58, 26, { stroke: AC, lw: 10 });
  A.circle(0, -45, 12, { fill: AC });
  ctx.restore();
  ctx.restore();
}

// ---------- ESTATUA (grupo que luego se desplaza) ----------
const shift = A.p(kM - 0.1, 0.75, 'glide');
const gScale = 1 - 0.12 * shift;
ctx.save();
ctx.translate(540 - 200 * shift, 1100);
ctx.scale(gScale, gScale);
ctx.translate(-540, -1100);

const drawP = A.p(kD + 0.05, 1.2, 'softLand');
const cut = A.p(kE - 0.1, 0.5, 'softInOut'); // piel translúcida
const body = [[450, 1100], [470, 940], [480, 800], [488, 700], [505, 675], [525, 668], [555, 668], [575, 675], [590, 690], [600, 620], [608, 545], [612, 522], [634, 527], [628, 600], [614, 690], [602, 760], [606, 900], [626, 1100], [450, 1100]];
if (drawP > 0) {
  // relleno de piel (cobre tenue)
  ctx.save();
  ctx.globalAlpha = 0.55 * A.p(kD + 0.9, 0.5) * (1 - 0.75 * cut);
  ctx.beginPath();
  body.forEach((q, i) => i ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1]));
  ctx.closePath();
  ctx.fillStyle = '#b8733a';
  ctx.fill();
  ctx.restore();
  if (cut < 0.5) A.lib.hatch(ctx, body, { angle: -0.7, spacing: 14, width: 1.5, color: 'rgba(255,255,255,' + (0.18 * (1 - cut * 2) * A.p(kD + 0.9, 0.5)) + ')' });
  const skinA = 1 - 0.6 * cut;
  A.line(body, { stroke: '#ffffff', lw: 5, progress: drawP, alpha: skinA, dash: cut > 0.5 ? [14, 10] : null });
  // tablilla
  A.line([[470, 730], [505, 735], [500, 830], [462, 822], [470, 730]], { stroke: '#ffffff', lw: 4, progress: A.p(kD + 0.6, 0.6), alpha: skinA });
  // cabeza y corona
  const hp = A.p(kD + 0.5, 0.6, 'softLand');
  A.circle(540, 640, 28 * hp, { stroke: '#ffffff', lw: 5, alpha: skinA });
  for (let i = 0; i < 7; i++) {
    const a = -Math.PI * (0.15 + 0.7 * i / 6);
    const sp = A.p(kD + 0.7 + i * 0.05, 0.4, 'popOver');
    A.line([[540 + Math.cos(a) * 30, 640 + Math.sin(a) * 30], [540 + Math.cos(a) * (30 + 40 * sp), 640 + Math.sin(a) * (30 + 40 * sp)]], { stroke: '#ffffff', lw: 4, alpha: skinA });
  }
  // antorcha
  const fl = A.p(kD + 1.1, 0.4, 'popOver');
  if (fl > 0) {
    const fy = 505 + Math.sin(t * 9) * 3;
    A.lib.glowDot(ctx, 623, fy, 22 * fl, { color: AC });
    A.circle(623, fy, 12 * fl, { fill: AC });
  }
}

// ---------- ESQUELETO DE HIERRO ----------
function truss(xl0, xl1, xr0, xr1, y0, y1, n, p, lw, col, a) {
  const L = [], R = [];
  for (let i = 0; i <= n; i++) {
    const f = i / n, y = A.lerp(y0, y1, f);
    L.push([A.lerp(xl0, xl1, f), y]); R.push([A.lerp(xr0, xr1, f), y]);
  }
  A.line(L, { stroke: col, lw: lw, progress: p, alpha: a });
  A.line(R, { stroke: col, lw: lw, progress: p, alpha: a });
  for (let i = 0; i < n; i++) {
    const bp = A.clamp(p * (n + 2) - i - 1);
    if (bp <= 0) continue;
    A.line([L[i], R[i + 1]], { stroke: col, lw: lw * 0.6, progress: bp, alpha: a });
    A.line([R[i], L[i + 1]], { stroke: col, lw: lw * 0.6, progress: bp, alpha: a });
    A.line([L[i + 1], R[i + 1]], { stroke: col, lw: lw * 0.6, progress: bp, alpha: a });
  }
}
const sk = A.p(kE, 1.3, 'softLand');
if (sk > 0) {
  truss(492, 520, 588, 560, 1095, 690, 8, sk, 6, AC, 1);
  // brazo
  const ap = A.p(kE + 0.8, 0.8, 'softLand');
  if (ap > 0) {
    const N = 5, L = [], R = [];
    for (let i = 0; i <= N; i++) { const f = i / N; L.push([A.lerp(570, 609, f), A.lerp(690, 535, f)]); R.push([A.lerp(588, 627, f), A.lerp(695, 540, f)]); }
    A.line(L, { stroke: AC, lw: 4, progress: ap }); A.line(R, { stroke: AC, lw: 4, progress: ap });
    for (let i = 0; i < N; i++) if (ap * N > i) A.line([L[i], R[i + 1]], { stroke: AC, lw: 2.5 });
  }
  // barras planas hacia la piel
  const bars = [[[492, 1000], [462, 1000]], [[588, 1000], [614, 1000]], [[498, 880], [474, 880]], [[581, 880], [604, 880]], [[505, 780], [482, 780]], [[574, 780], [602, 780]]];
  bars.forEach((b, i) => A.line(b, { stroke: '#ffffff', lw: 2.5, progress: A.p(kH + i * 0.06, 0.3), alpha: 0.8 }));
  A.rings(540, 890, kEi, { count: 3, speed: 420, gap: 0.18, maxR: 330, color: AC, lw: 4, alpha: 0.7 });
}

// callouts dentro del grupo
const pielA = A.p(kB, 0.35) * (1 - A.p(kE + 0.2, 0.4));
if (pielA > 0) {
  A.arrow(330, 880, 465, 880, { progress: A.p(kB, 0.4, 'glide'), color: '#ffffff', lw: 5, alpha: pielA });
  A.label('PIEL', 260, 880, { size: 44, bg: '#ffffff', color: '#0b1630', scale: A.pop(kB, 0.45), alpha: pielA });
}
const ferA = A.p(kH, 0.35) * (1 - A.p(kM - 0.2, 0.4));
if (ferA > 0) {
  A.arrow(780, 960, 600, 960, { progress: A.p(kH, 0.4, 'glide'), color: AC, lw: 5, alpha: ferA });
  A.label('HIERRO', 850, 960, { size: 44, bg: AC, color: '#0b1630', scale: A.pop(kH, 0.45), alpha: ferA });
}
ctx.restore();

// ---------- TORRE EIFFEL ----------
const tw = A.p(kM - 0.05, 1.1, 'softLand');
if (tw > 0) {
  const cx = 850, yb = 1100, yt = 560;
  const hw = y => 8 + 112 * Math.pow((y - yt) / (yb - yt), 2.2);
  const n = 10, L = [], R = [];
  for (let i = 0; i <= n; i++) { const y = A.lerp(yb, yt, i / n); L.push([cx - hw(y), y]); R.push([cx + hw(y), y]); }
  A.line(L, { stroke: AC, lw: 6, progress: tw }); A.line(R, { stroke: AC, lw: 6, progress: tw });
  for (let i = 0; i < n; i++) {
    const bp = A.clamp(tw * (n + 2) - i - 1);
    if (bp <= 0) continue;
    A.line([L[i], R[i + 1]], { stroke: AC, lw: 2.5, progress: bp });
    A.line([R[i], L[i + 1]], { stroke: AC, lw: 2.5, progress: bp });
  }
  // arco y plataformas
  const ap = A.p(kM + 0.3, 0.5);
  if (ap > 0) {
    ctx.save(); ctx.globalAlpha = ap; ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(cx, yb + 10, 70, Math.PI, 2 * Math.PI); ctx.stroke(); ctx.restore();
    [[990, 1], [800, 1]].forEach(([y]) => A.line([[cx - hw(y) - 12, y], [cx + hw(y) + 12, y]], { stroke: '#ffffff', lw: 6, progress: ap }));
  }
  A.circle(cx, yt - 18, 6 * tw, { fill: AC, glow: 20 });
}

// signo igual
const eq = A.pop(kT - 0.15, 0.5);
if (eq > 0) {
  A.with(() => {
    A.rect(-34, -22, 68, 14, { r: 6, fill: '#ffffff' });
    A.rect(-34, 8, 68, 14, { r: 6, fill: '#ffffff' });
  }, { x: 660, y: 850, scale: eq });
}

// ---------- ZONA SECUNDARIA: etiquetas grandes ----------
function tag(str, start, end, bg, col, size) {
  const a = A.p(start, 0.3) * (1 - A.p(end, 0.3));
  if (a <= 0) return;
  A.label(str, 540, 1470, { size: size || 64, bg: bg, color: col, scale: A.pop(start, 0.45), alpha: a });
}
// Francia con mini bandera
const fa = A.p(kF, 0.3) * (1 - A.p(kD + 0.2, 0.3));
if (fa > 0) {
  A.with(() => {
    A.rect(-200, -45, 40, 90, { fill: '#2b55d6' });
    A.rect(-160, -45, 40, 90, { fill: '#ffffff' });
    A.rect(-120, -45, 40, 90, { fill: '#e2384a' });
    A.text('FRANCIA', 60, 22, { size: 70, color: '#ffffff', weight: 900, align: 'center' });
  }, { x: 540, y: 1470, scale: A.pop(kF, 0.45), alpha: fa });
  A.text('un regalo', 540, 1580, { size: 40, color: AC, weight: 700, align: 'center', alpha: fa });
}
tag('BARTHOLDI · FORMA', kB, kE, '#ffffff', '#0b1630', 58);
tag('ESQUELETO DE HIERRO', kE + 0.1, kG, AC, '#0b1630', 56);
tag('GUSTAVE EIFFEL', kG, kM + 0.4, AC, '#0b1630', 72);
tag('MISMO INGENIERO', kM + 0.4, A.dur + 1, '#ffffff', '#0b1630', 64);

A.flash(kEi, 0.3, 0.35);

A.bg('#0B1626','#060B14',true);
const acc=A.accent;
const S=22;
function inside(x,y){
  const dx=Math.abs(x-540);
  // pedestal escalonado
  if(y>=1060&&y<=1100&&dx<=132) return 'b';
  if(y>=1016&&y<1060&&dx<=100) return 'b';
  if(y>=970&&y<1016&&dx<=70) return 'b';
  // tunica
  if(y>=640&&y<970){const f=(y-640)/330;const hw=(y<660?50:36+30*f);if(dx<=hw) return 'b';}
  // cabeza + cuello
  if(Math.hypot(x-540,y-607)<=30) return 'b';
  if(y>620&&y<640&&dx<=22) return 'b';
  // corona con picos
  if(y>552&&y<574&&dx<=44) return 'c';
  if(y>530&&y<552&&(x===496||x===540||x===584)) return 'c';
  if(y>508&&y<530&&x===540) return 'c';
  // brazo derecho levantado
  if(x===606&&y>=497&&y<=629) return 'b';
  if(x===584&&y>=620&&y<=660) return 'b';
  if(x===606&&y>470&&y<480) return 'b';
  // antorcha (llama)
  if(y>442&&y<464&&(x===584||x===606||x===628)) return 'f';
  if(y>420&&y<442&&x===606) return 'f';
  // tablilla + antebrazo
  if((x===452||x===474)&&y>=695&&y<=783) return 't';
  if(x===496&&y>=717&&y<=739) return 'b';
  return false;
}
const P=[];
for(let y=431;y<=1091;y+=S) for(let x=386;x<=694;x+=S){const ty=inside(x,y); if(ty) P.push({x,y,ty});}
const n=P.length;
const kC=A.k('completa',1.0), kP=A.k('París',1.667);
const kDes=A.k('después',2.333), kD=A.k('desarmaron',3.0), kPz=A.k('piezas',4.667);

const cols=18, gap=34, rows=Math.ceil(n/cols);
const gx0=540-(cols-1)*gap/2, gy0=770-(rows-1)*gap/2;

const shake = t>kD ? (1-A.p(kD,0.45,'cruise'))*12 : 0;
const breathe = 1+0.012*Math.sin(t*3)*A.p(kC,0.5,'softInOut')*(t<kD?1:0);
const sweep = A.p(kDes,kD-kDes-0.05,'cruise');
const sweepY = A.lerp(425,1105,sweep);

// pulso PARIS centrado en la estatua (no baja de ~1110)
if(t>kP-0.1&&t<kD+0.4) A.rings(540,780,kP,{count:3,speed:240,gap:0.2,maxR:320,color:acc,lw:4,alpha:0.5});

